def inputs(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    products_table = None
    ledger_table = None
    future_table = None
    for cid in children(doc, scope_node):
        c = node_by_id(doc, cid)
        t = c.get("title", "")
        k = c.get("kind")
        if k == "table":
            if "Products" in t and "Order book" not in t:
                products_table = c
            elif "Daily ledger" in t:
                ledger_table = c
            elif "production planned" in t.lower() or "Orders received" in t:
                future_table = c

    result = []

    # Opening stock / product attributes (initial state)
    if products_table:
        for ri, r in table_rows(products_table):
            p = r["product"]
            result.append({
                "id": f"init_{p}",
                "time": 1.0,
                "kind": "initial_state",
                "entities": [p],
                "fields": {
                    "opening_stock": int(r["opening stock"]),
                    "kg_per_unit": int(r["kg per unit"])
                },
                "src": [[products_table["node_id"], ri, ["product", "opening stock", "kg per unit"]]]
            })

    # Daily production (amount supplied) and orders (external requests)
    if ledger_table:
        for ri, r in table_rows(ledger_table):
            d = int(r["day"])
            p = r["product"]
            produced = int(r["produced"])
            ordered = int(r["ordered"])

            result.append({
                "id": f"production_{d}_{p}",
                "time": float(d),
                "kind": "production_arrival",
                "entities": [p],
                "fields": {"produced": produced},
                "src": [[ledger_table["node_id"], ri, ["day", "product", "produced"]]]
            })

            if ordered > 0:
                result.append({
                    "id": f"order_{d}_{p}",
                    "time": float(d),
                    "kind": "order_placed",
                    "entities": [p],
                    "fields": {"ordered": ordered},
                    "src": [[ledger_table["node_id"], ri, ["day", "product", "ordered"]]]
                })

    # Future planned production and orders (from Order book)
    if future_table:
        for ri, r in table_rows(future_table):
            d = int(r["day"])
            p = r["product"]
            planned = int(r["planned production"])
            ordered = int(r["ordered"])

            result.append({
                "id": f"planned_prod_{d}_{p}",
                "time": float(d),
                "kind": "planned_production",
                "entities": [p],
                "fields": {"planned_production": planned},
                "src": [[future_table["node_id"], ri, ["day", "product", "planned production"]]]
            })

            if ordered > 0:
                result.append({
                    "id": f"planned_order_{d}_{p}",
                    "time": float(d),
                    "kind": "planned_order",
                    "entities": [p],
                    "fields": {"ordered": ordered},
                    "src": [[future_table["node_id"], ri, ["day", "product", "ordered"]]]
                })

    return result

def outcomes(doc, scope) -> list:
    scope_node = node_by_title(doc, scope)
    ledger_table = None
    events_list = None
    for cid in children(doc, scope_node):
        c = node_by_id(doc, cid)
        t = c.get("title", "")
        k = c.get("kind")
        if k == "table" and "Daily ledger" in t:
            ledger_table = c
        elif k == "list" and "Events" in t:
            events_list = c

    # Collect product codes for entity matching in events
    product_codes = set()
    for cid in children(doc, scope_node):
        c = node_by_id(doc, cid)
        if c.get("kind") == "table" and "Products" in c.get("title", "") and "Order book" not in c.get("title", ""):
            for _, r in table_rows(c):
                product_codes.add(r["product"])

    result = []

    # Shipped, backordered, stock — computed by the dispatch process
    if ledger_table:
        for ri, r in table_rows(ledger_table):
            d = int(r["day"])
            p = r["product"]
            for kind, col in [("shipped", "shipped"), ("backordered", "backordered"), ("stock", "stock")]:
                result.append({
                    "time": float(d),
                    "kind": kind,
                    "entities": [p],
                    "value": int(r[col]),
                    "src": [[ledger_table["node_id"], ri, ["day", "product", col]]]
                })

    # Events — capacity reached, stock-outs, fully backordered, backlog cleared
    if events_list:
        for li, line in enumerate(events_list.get("lines", [])):
            if line.strip():
                dm = re.match(r'Day (\d+)', line)
                if dm:
                    d = int(dm.group(1))
                    ents = [pc for pc in product_codes if pc in line]
                    result.append({
                        "time": float(d),
                        "kind": "event",
                        "entities": ents,
                        "value": None,
                        "src": [[events_list["node_id"], li]]
                    })

    return result

def params(doc, scope) -> dict:
    scope_node = node_by_title(doc, scope)
    for cid in children(doc, scope_node):
        c = node_by_id(doc, cid)
        if c.get("kind") == "text":
            m = re.search(r'Daily dispatch capacity:\s*(\d+)\s*kg', c.get("text", ""))
            if m:
                return {"dispatch_capacity_kg": int(m.group(1))}
    return {}

